        if (!notification) {
            return;
        }

        const secureLinks = () => {
            notification.querySelectorAll('a').forEach((link) => {
                if (link.getAttribute('rel') !== 'noopener noreferrer') {
                    link.setAttribute('rel', 'noopener noreferrer');
                }
                if (link.getAttribute('target') !== '_blank') {
                    link.setAttribute('target', '_blank');
                }
